update rt.no n set tarefa = t.id from org.tarefa t join org.etapa e on e.id = t.etapa where e.jornada = n.jornada and e.numero = n.etapa_numero and t.ordem = n.ordem;
do $$ declare k int; begin
  select count(*) into k from rt.no where ordem is not null and tarefa is null;
  if k > 0 then raise exception 'tarefas do BPMN sem tarefa no modelo: %', k; end if;
  select count(*) into k from rt.no n join org.tarefa t on t.id = n.tarefa where n.nome is distinct from t.nome;
  if k > 0 then raise exception 'tarefas com nome diferente do modelo: %', k; end if;
  select count(*) into k from org.tarefa t where not exists (select 1 from rt.no n where n.tarefa = t.id);
  if k > 0 then raise exception 'tarefas do modelo fora do BPMN: %', k; end if;
end $$;
select 'GRAFOS: ' || count(*) || ' jornadas trocadas: ' || coalesce(string_agg(j, ', ' order by j), '') from _mudou;
